with open('style.css', 'r', encoding='utf-8') as f:
    css = f.read()

# Fix opacity and mask-image
css = css.replace('''  .maze-art{
    position:absolute;
    inset:0;
    width:100%;
    height:100%;
    background-image:url('data:image/svg+xml;base64,');
    background-repeat:no-repeat;
    background-position:center;
    background-size:cover;
    opacity:1;
    z-index:0;
  }''', '''  .maze-art{
    position:absolute;
    inset:0;
    width:100%;
    height:100%;
    background-image:url('data:image/svg+xml;base64,');
    background-repeat:no-repeat;
    background-position:center;
    background-size:cover;
    opacity:.32;
    z-index:0;
    pointer-events:none;
    mask-image: linear-gradient(180deg, black 0%, black 60%, transparent 96%);
  }''')

with open('style.css', 'w', encoding='utf-8') as f:
    f.write(css)

with open('index.html', 'r', encoding='utf-8') as f:
    html = f.read()

html = html.replace('<span class="btn-icon">🪙</span>', '<span class="btn-icon">👾</span>')
html = html.replace('<span class="btn-icon">📖</span>', '<span class="btn-icon">📜</span>')

with open('index.html', 'w', encoding='utf-8') as f:
    f.write(html)
